            codeExample: 'type User = {\n  id: number\n  name: string\n}\n\nconst users: User[] = [\n  { id: 1, name: "Alice" },\n  { id: 2, name: "Bob" },\n]\n\nusers.forEach(user => {\n  console.log(user.name.toUpperCase())  // autocomplete works!\n})',
